import {
  MAX_COUPON_PERCENTAGE,
  MAX_ITEM_QUANTITY,
  cartStatuses,
  couponTypes,
} from "@aigile/shared";
import { sql } from "drizzle-orm";
import {
  bigint,
  check,
  integer,
  pgTable,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";

export const products = pgTable(
  "products",
  {
    // Generated by the database with gen_random_uuid() (ADR 0006).
    id: uuid("id").primaryKey().defaultRandom(),
    name: text("name").notNull(),
    description: text("description").notNull().default(""),
    // Money as integer cents (ADR 0005).
    priceCents: integer("price_cents").notNull(),
    stock: integer("stock").notNull(),
  },
  (table) => [
    check("products_price_cents_non_negative", sql`${table.priceCents} >= 0`),
    check("products_stock_non_negative", sql`${table.stock} >= 0`),
  ],
);

export const coupons = pgTable(
  "coupons",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Stored in upper case so the lookup is case-insensitive (FRD, "Regras do Coupon").
    code: text("code").notNull().unique("coupons_code_unique"),
    type: text("type", { enum: couponTypes }).notNull(),
    // A percentage (1 to 100) or integer cents greater than zero, by type.
    value: integer("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
  },
  (table) => [
    check("coupons_code_upper_case", sql`${table.code} = upper(${table.code})`),
    check(
      "coupons_type_known",
      sql`${table.type} IN (${sql.raw(couponTypes.map((type) => `'${type}'`).join(", "))})`,
    ),
    check(
      "coupons_value_matches_type",
      sql`(${table.type} = 'percentage' AND ${table.value} BETWEEN 1 AND ${sql.raw(String(MAX_COUPON_PERCENTAGE))}) OR (${table.type} = 'fixed' AND ${table.value} > 0)`,
    ),
  ],
);

export const carts = pgTable(
  "carts",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Generated by the Shopper's browser; not a key of anything (FRD, "Identidade do Shopper").
    shopperId: uuid("shopper_id").notNull(),
    status: text("status", { enum: cartStatuses }).notNull().default("empty"),
    // Set from the injected clock on every successful mutation; reads leave it alone.
    lastChangedAt: timestamp("last_changed_at", { withTimezone: true }).notNull(),
    // The applied Coupon, at most one; null when there is none.
    couponId: uuid("coupon_id").references(() => coupons.id),
  },
  (table) => [
    check(
      "carts_status_known",
      sql`${table.status} IN (${sql.raw(cartStatuses.map((status) => `'${status}'`).join(", "))})`,
    ),
  ],
);

export const cartItems = pgTable(
  "cart_items",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    cartId: uuid("cart_id")
      .notNull()
      .references(() => carts.id, { onDelete: "cascade" }),
    productId: uuid("product_id")
      .notNull()
      .references(() => products.id),
    quantity: integer("quantity").notNull(),
    // The Product's price when it entered the Cart; later price changes do not follow.
    unitPriceCents: integer("unit_price_cents").notNull(),
    // Internal ordering of the items by when they entered the Cart; never exposed (ADR 0006).
    insertionOrder: bigint("insertion_order", { mode: "number" }).generatedAlwaysAsIdentity(),
  },
  (table) => [
    unique("cart_items_cart_product_unique").on(table.cartId, table.productId),
    check(
      "cart_items_quantity_range",
      sql`${table.quantity} BETWEEN 1 AND ${sql.raw(String(MAX_ITEM_QUANTITY))}`,
    ),
    check("cart_items_unit_price_cents_non_negative", sql`${table.unitPriceCents} >= 0`),
  ],
);
